package org.jlinalg.cli;

import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import org.jlinalg.timeseries.ArimaForecast;
import org.jlinalg.timeseries.ArimaOptions;
import org.jlinalg.timeseries.ArimaOrder;
import org.jlinalg.timeseries.ArimaRegression;
import org.jlinalg.timeseries.SeasonalArimaOrder;

/** ARIMA-error regression, scalable smoothing, and forecast command. */
final class ArimaRegressionCli {
    private ArimaRegressionCli() { }
    static int run(String[] args,PrintStream output,PrintStream error){try{Options o=Options.parse(args);if(o.help){output.println(help());return 0;}CliNumericTable table=CliNumericTable.read(o.input);double[] y=table.column(o.response);double[][] design=table.design(o.predictors,o.intercept);ArimaOptions.Builder builder=ArimaOptions.builder().includeMean(false).optimizationStarts(o.starts).maximumFunctionEvaluations(o.maximumEvaluations).optimizationTolerance(o.tolerance);if(o.seasonalPeriod>0)builder.seasonalOrder(SeasonalArimaOrder.of(o.seasonalP,o.seasonalD,o.seasonalQ,o.seasonalPeriod));ArimaRegression.Result fit=ArimaRegression.fit(y,design,ArimaOrder.arima(o.p,o.d,o.q),builder.build());if(!fit.converged())throw new IllegalArgumentException("ARIMA regression did not converge");List<Path> outputs=new ArrayList<>();outputs.add(suffix(o.output,".model.tsv"));if(o.smooth)outputs.add(suffix(o.output,".smoothed.tsv"));if(o.horizon>0)outputs.add(suffix(o.output,".forecast.tsv"));outputs.add(suffix(o.output,".manifest.tsv"));for(Path path:outputs)if(Files.exists(path)&&!o.overwrite)throw new IOException("output exists; use --overwrite: "+path);int index=0;writeModel(outputs.get(index++),fit,o,design[0].length);if(o.smooth)writeSmooth(outputs.get(index++),fit.smoothErrors(),y);if(o.horizon>0){double[][] future=futureDesign(o,design[0].length);ArimaForecast forecast=o.parameterUncertainty?fit.forecastWithParameterUncertainty(future,o.confidence):fit.forecastConditional(future,o.confidence);writeForecast(outputs.get(index++),forecast);}writeManifest(outputs.get(index),fit,o,table.rows());output.printf(Locale.ROOT,"observations=%d regression_parameters=%d ar_order=%d ma_order=%d converged=%s joint_inference=%s%n",table.rows(),fit.coefficients().length,fit.effectiveAutoregressive().length,fit.effectiveMovingAverage().length,fit.converged(),fit.jointParameterInferenceAvailable());return 0;}catch(IOException|IllegalArgumentException failure){error.println("jlinalg: "+failure.getMessage());return 2;}}
    private static double[][] futureDesign(Options o,int columns)throws IOException{if(o.future!=null){CliNumericTable future=CliNumericTable.read(o.future);double[][] result=future.design(o.predictors,o.intercept);if(result.length!=o.horizon)throw new IllegalArgumentException("future data rows must equal --horizon");return result;}if(!o.predictors.isEmpty())throw new IllegalArgumentException("forecasting with predictors requires --future");double[][] result=new double[o.horizon][columns];if(o.intercept)for(double[] row:result)row[0]=1.0;return result;}
    private static void writeModel(Path path,ArimaRegression.Result fit,Options o,int regressionColumns)throws IOException{StringBuilder text=new StringBuilder("component\tindex\testimate\n");double[] coefficients=fit.coefficients();for(int i=0;i<coefficients.length;i++)text.append("regression\t").append(i+1).append('\t').append(coefficients[i]).append('\n');double[] ar=fit.effectiveAutoregressive(),ma=fit.effectiveMovingAverage();for(int i=0;i<ar.length;i++)text.append("effective_ar\t").append(i+1).append('\t').append(ar[i]).append('\n');for(int i=0;i<ma.length;i++)text.append("effective_ma\t").append(i+1).append('\t').append(ma[i]).append('\n');text.append("innovation_variance\t0\t").append(fit.innovationVariance()).append('\n').append("log_likelihood\t0\t").append(fit.logLikelihood()).append('\n');write(path,text.toString());}
    private static void writeSmooth(Path path,org.jlinalg.timeseries.ArimaSmoothing.Result smooth,double[] observed)throws IOException{StringBuilder text=new StringBuilder("time\tobserved\tsmoothed_error_signal\tsignal_variance\n");for(int i=0;i<observed.length;i++)text.append(i+1).append('\t').append(Double.isNaN(observed[i])?"NA":observed[i]).append('\t').append(smooth.signal()[i]).append('\t').append(smooth.signalVariance()[i]).append('\n');write(path,text.toString());}
    private static void writeForecast(Path path,ArimaForecast forecast)throws IOException{StringBuilder text=new StringBuilder("step\tmean\tstandard_error\tlower\tupper\n");double[] mean=forecast.means(),se=forecast.standardErrors(),lo=forecast.lowerBounds(),hi=forecast.upperBounds();for(int i=0;i<mean.length;i++)text.append(i+1).append('\t').append(mean[i]).append('\t').append(se[i]).append('\t').append(lo[i]).append('\t').append(hi[i]).append('\n');write(path,text.toString());}
    private static void writeManifest(Path path,ArimaRegression.Result fit,Options o,int observations)throws IOException{String text="key\tvalue\nmethod\tarima-regression\nobservations\t"+observations+"\norder\t"+o.p+","+o.d+","+o.q+"\nseasonal_order\t"+o.seasonalP+","+o.seasonalD+","+o.seasonalQ+","+o.seasonalPeriod+"\nconverged\t"+fit.converged()+"\nlog_likelihood\t"+fit.logLikelihood()+"\ninnovation_variance\t"+fit.innovationVariance()+"\nparameter_uncertainty_forecast\t"+o.parameterUncertainty+"\n";write(path,text);}
    private static void write(Path path,String text)throws IOException{Path parent=path.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);Files.writeString(path,text,StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
    private static Path suffix(Path prefix,String suffix){return Path.of(prefix.toString()+suffix);}
    private static String help(){return """
        Usage: java -jar jlinalg.jar arima-regression --input TABLE --response Y
          [--predictors x1,x2] --order p,d,q --out PREFIX [--smooth]
          [--seasonal P,D,Q,period] [--horizon N --future TABLE]
          [--parameter-uncertainty] [--confidence-level 0.95]
        Smoothing uses the linear-memory exact backward information smoother.
        Forecast predictors must contain exactly --horizon rows.
        """;}
    private static final class Options{boolean help,overwrite,intercept=true,smooth,parameterUncertainty;Path input,output,future;String response;List<String> predictors=List.of();int p,d,q,seasonalP,seasonalD,seasonalQ,seasonalPeriod,horizon,starts=1,maximumEvaluations=2000;double tolerance=1e-8,confidence=.95;static Options parse(String[] args){Options o=new Options();boolean order=false;for(int i=0;i<args.length;i++){String a=args[i];switch(a){case "--help","-h"->o.help=true;case "--overwrite"->o.overwrite=true;case "--no-intercept"->o.intercept=false;case "--smooth"->o.smooth=true;case "--parameter-uncertainty"->o.parameterUncertainty=true;case "--input"->o.input=Path.of(value(args,++i,a));case "--out"->o.output=Path.of(value(args,++i,a));case "--future"->o.future=Path.of(value(args,++i,a));case "--response"->o.response=value(args,++i,a);case "--predictors"->o.predictors=CliNumericTable.columns(value(args,++i,a));case "--order"->{int[] v=integers(value(args,++i,a),3,a);o.p=v[0];o.d=v[1];o.q=v[2];order=true;}case "--seasonal"->{int[] v=integers(value(args,++i,a),4,a);o.seasonalP=v[0];o.seasonalD=v[1];o.seasonalQ=v[2];o.seasonalPeriod=v[3];}case "--horizon"->o.horizon=nonnegative(value(args,++i,a),a);case "--starts"->o.starts=positive(value(args,++i,a),a);case "--max-evaluations"->o.maximumEvaluations=positive(value(args,++i,a),a);case "--tolerance"->o.tolerance=positiveDouble(value(args,++i,a),a);case "--confidence-level"->o.confidence=Double.parseDouble(value(args,++i,a));default->throw new IllegalArgumentException("unknown option: "+a);}}if(o.help)return o;if(o.input==null||o.output==null||o.response==null||!order)throw new IllegalArgumentException("--input, --response, --order, and --out are required");if(o.future!=null&&o.horizon<1)throw new IllegalArgumentException("--future requires positive --horizon");if(o.parameterUncertainty&&o.horizon<1)throw new IllegalArgumentException("--parameter-uncertainty requires a forecast horizon");if(!(o.confidence>0&&o.confidence<1))throw new IllegalArgumentException("confidence level must be in (0,1)");return o;}private static String value(String[] a,int i,String option){if(i>=a.length||a[i].isBlank())throw new IllegalArgumentException(option+" requires a value");return a[i];}private static int[] integers(String x,int count,String option){String[] values=x.split(",",-1);if(values.length!=count)throw new IllegalArgumentException(option+" requires "+count+" comma-separated integers");int[] result=new int[count];for(int i=0;i<count;i++)result[i]=nonnegative(values[i].trim(),option);return result;}private static int nonnegative(String x,String option){int r=Integer.parseInt(x);if(r<0)throw new IllegalArgumentException(option+" must be nonnegative");return r;}private static int positive(String x,String option){int r=Integer.parseInt(x);if(r<1)throw new IllegalArgumentException(option+" must be positive");return r;}private static double positiveDouble(String x,String option){double r=Double.parseDouble(x);if(!(r>0)||!Double.isFinite(r))throw new IllegalArgumentException(option+" must be positive and finite");return r;}}
}
